uniform 	float _DisturbVSpeed;
uniform 	vec4 _DisturbTex_ST;
uniform 	float _DisturbIntensity;
uniform 	float _DisturbModeCtrl;
uniform 	vec4 _DisturbMask_ST;
uniform 	vec4 _MainColor;
uniform 	float _DissolveSoftness;
uniform 	vec4 _DissolveMask_ST;
uniform 	float _DissolveMaskRotate;
uniform 	float _DissolveSpeedU;
uniform 	float _DissolveSpeedV;
uniform 	vec4 _DissolveTex_ST;
uniform 	float _DissolveIntensity;
