};
#endif
UNITY_LOCATION(0) uniform mediump sampler2D _DisturbTex;
UNITY_LOCATION(1) uniform mediump sampler2D _DisturbMask;
UNITY_LOCATION(2) uniform mediump sampler2D _MainTex;
UNITY_LOCATION(3) uniform mediump sampler2D _ParticleTex;
UNITY_LOCATION(4) uniform mediump sampler2D _DissolveMask;
UNITY_LOCATION(5) uniform mediump sampler2D _DissolveTex;
in mediump vec4 vs_COLOR0;
in mediump vec2 vs_TEXCOORD0;
layout(location = 0) out mediump vec4 SV_Target0;
vec4 u_xlat0;
mediump vec2 u_xlat16_0;
vec4 u_xlat1;
mediump vec4 u_xlat16_1;
vec3 u_xlat2;
mediump vec4 u_xlat16_2;
vec3 u_xlat3;
mediump vec2 u_xlat16_4;
vec2 u_xlat5;
mediump float u_xlat16_5;
vec2 u_xlat10;
mediump vec2 u_xlat16_10;
vec2 u_xlat11;
float u_xlat15;
mediump float u_xlat16_15;
void main()
