    u_xlat10.x = _DissolveMaskRotate * 0.0174532924;
    u_xlat1.x = sin(u_xlat10.x);
    u_xlat2.x = cos(u_xlat10.x);
    u_xlat3.z = u_xlat1.x;
    u_xlat3.y = u_xlat2.x;
    u_xlat3.x = (-u_xlat1.x);
    u_xlat1.y = dot(u_xlat0.xy, u_xlat3.xy);
    u_xlat1.x = dot(u_xlat0.xy, u_xlat3.yz);
    u_xlat0.xy = u_xlat1.xy + vec2(0.5, 0.5);
    u_xlat16_0.xy = texture(_DissolveMask, u_xlat0.xy).xw;
    u_xlat0.x = u_xlat16_0.y * u_xlat16_0.x;
    u_xlat5.xy = vs_TEXCOORD0.xy * _DisturbTex_ST.xy + _DisturbTex_ST.zw;
    u_xlat5.xy = _Time.yy * vec2(_DisturbUSpeed, _DisturbVSpeed) + u_xlat5.xy;
    u_xlat16_5 = texture(_DisturbTex, u_xlat5.xy).x;
    u_xlat5.x = u_xlat16_5 + -0.5;
    u_xlat5.x = u_xlat5.x + u_xlat5.x;
    u_xlat10.x = u_xlat5.x * _DisturbIntensity;
    u_xlat1.xy = vs_TEXCOORD0.xy * _DissolveTex_ST.xy + _DissolveTex_ST.zw;
    u_xlat10.xy = u_xlat10.xx * vec2(0.100000001, 0.100000001) + u_xlat1.xy;
    u_xlat1.xy = (-u_xlat10.xy) + vs_TEXCOORD0.xy;
    u_xlat10.xy = vec2(vec2(_DisturbModeCtrl, _DisturbModeCtrl)) * u_xlat1.xy + u_xlat10.xy;
    u_xlat10.xy = _Time.yy * vec2(_DissolveSpeedU, _DissolveSpeedV) + u_xlat10.xy;
    u_xlat16_10.xy = texture(_DissolveTex, u_xlat10.xy).xw;
    u_xlat10.x = u_xlat16_10.y * u_xlat16_10.x;
    u_xlat0.x = u_xlat10.x * u_xlat0.x;
    u_xlat0.x = clamp(u_xlat0.x, 0.0, 1.0);
    u_xlat10.x = _DissolveSoftness * 0.5;
    u_xlat15 = (-_DissolveSoftness) + 1.04999995;
    u_xlat16_4.xy = (-vs_COLOR0.xy) + vec2(1.0, 1.0);
    u_xlat1.x = (-u_xlat16_4.y) + _DissolveIntensity;
    u_xlat1.x = _RgbCtrl * u_xlat1.x + u_xlat16_4.y;
    u_xlat10.x = u_xlat1.x * u_xlat15 + u_xlat10.x;
    u_xlat10.x = u_xlat10.x * -1.04999995 + 0.549999952;
    u_xlat0.x = u_xlat10.x * 2.0 + u_xlat0.x;
    u_xlat0.x = u_xlat0.x + (-_DissolveSoftness);
    u_xlat10.x = _DissolveSoftness * -2.0 + 1.0;
    u_xlat10.x = float(1.0) / u_xlat10.x;
    u_xlat0.x = u_xlat10.x * u_xlat0.x;
    u_xlat0.x = clamp(u_xlat0.x, 0.0, 1.0);
    u_xlat10.x = u_xlat0.x * -2.0 + 3.0;
    u_xlat0.x = u_xlat0.x * u_xlat0.x;
    u_xlat0.x = u_xlat0.x * u_xlat10.x;
    u_xlat10.x = (-u_xlat16_4.x) + 1.0;
    u_xlat10.x = _RgbCtrl * u_xlat10.x + u_xlat16_4.x;
    u_xlat10.x = u_xlat10.x * _DisturbIntensity;
    u_xlat5.x = u_xlat5.x * u_xlat10.x;
    u_xlat5.xy = u_xlat5.xx * vec2(0.100000001, 0.100000001) + vs_TEXCOORD0.xy;
    u_xlat1.xy = vs_TEXCOORD0.xy * _ParticleTex_ST.xy + _ParticleTex_ST.zw;
    u_xlat5.xy = u_xlat5.xy + (-u_xlat1.xy);
    u_xlat11.xy = vs_TEXCOORD0.xy * _DisturbMask_ST.xy + _DisturbMask_ST.zw;
    u_xlat16_15 = texture(_DisturbMask, u_xlat11.xy).x;
    u_xlat5.xy = vec2(u_xlat16_15) * u_xlat5.xy + u_xlat1.xy;
    u_xlat16_1 = texture(_MainTex, u_xlat5.xy);
    u_xlat16_2 = texture(_ParticleTex, u_xlat5.xy);
    u_xlat1 = u_xlat16_1 * u_xlat16_2;
    u_xlat5.x = u_xlat1.w * vs_COLOR0.w;
    u_xlat5.x = u_xlat5.x * _MainColor.w;
    u_xlat0.w = u_xlat0.x * u_xlat5.x;
    u_xlat2.xyz = vs_COLOR0.xyz + vec3(-1.0, -1.0, -1.0);
    u_xlat2.xyz = vec3(_RgbCtrl) * u_xlat2.xyz + vec3(1.0, 1.0, 1.0);
    u_xlat1.xyz = u_xlat1.xyz * u_xlat2.xyz;
    u_xlat0.xyz = u_xlat1.xyz * _MainColor.xyz;
    u_xlat0 = u_xlat0 * vec4(vec4(_MainIntensity, _MainIntensity, _MainIntensity, _MainIntensity));
    SV_Target0 = u_xlat0;
    return;
}

